from collections import deque
H=W=20; k=4
valid=set()
for r in range(H-k+1):
 for c in range(W-k+1):
  if all(rows[i][j]!='3' for i in range(r,r+k) for j in range(c,c+k)):
   valid.add((r,c))
start=(11,1)
q=deque([start]); seen={start}
while q:
 r,c=q.popleft()
 for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
  if p in valid and p not in seen: seen.add(p); q.append(p)
len(valid),len(seen),sorted(seen),[(p,sum((p[0]+dr,p[1]+dc) in seen for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)])) for p in sorted(seen)]

out=[list(x) for x in rows]
for r in range(11,15):
 for c in range(1,5): out[r][c]='1'
for r in range(1,5):
 for c in range(4,8): out[r][c]='0'
print('\n'.join(' '.join(x) for x in out))
